    mats = config['test_transpose_matrices']
    for mat in mats:
        trans = linalg.transpose(mat)
        back = linalg.transpose(trans)
        assert close_enough_matrix(mat, back, config['tolerance_matrix_eq'])
    print('Transpose test passed')

