    mats = config['test_inverse_matrices']
    for mat in mats:
        inv = linalg.gauss_jordan_inverse(mat)
        prod = linalg.multiply(mat, inv)
        identity = [[float(i==j) for j in range(len(mat))] for i in range(len(mat))]
        assert close_enough_matrix(prod, identity, config['tolerance_matrix_eq'])
    print('Inverse test passed')

def test_solve():
    for test in config['test_solve_systems']:
        A = test['A']
        b = test['b']
        expected = test['expected_solution']
